def main():
    raw, out = sys.argv[1:3]
    L = open(raw, encoding='utf-8').read().split('\n')
    # 2. edits (before swapping, coordinates are original raw line numbers)
    for ln, ti, old, new in EDITS:
        toks = L[ln - 1].split()
        if toks[ti] != old:
            sys.exit(f'אי־התאמה בשורה {ln} מילה {ti}')
        toks[ti] = new
        L[ln - 1] = ' '.join(toks)
    # 1. swaps
    for n in SWAPS:
        L[n - 2], L[n - 1] = L[n - 1], L[n - 2]
    # 3. strip points
    L = [re.sub(r'[\u0591-\u05bd\u05bf-\u05c7]', '', l) for l in L]
    with tempfile.NamedTemporaryFile('w', encoding='utf-8', suffix='.txt', delete=False) as f:
        f.write('\n'.join(L)); tmp = f.name
    try:
        subprocess.run([sys.executable, '-X', 'utf8',
                        os.path.join(os.path.dirname(os.path.abspath(__file__)), 'pachad_yitzchak_reflow.py'),
                        tmp, out], check=True)
    finally:
        os.unlink(tmp)


if __name__ == '__main__':
    main()
